# step_04: find closure candidates among given nodes within window [33039,45039]
nodes_list = [18,26,59,102,150,168,173,196,216,248,255,269]
start, end = 33039, 45039
# build undirected times
und = {}
neighbors = {}
for (u,v,t) in events:
    key = (u,v) if u<v else (v,u)
    und.setdefault(key, []).append(t)
    neighbors.setdefault(u, set()).add(v)
    neighbors.setdefault(v, set()).add(u)
# sort times
for k in und:
    und[k].sort()

results = []
from itertools import combinations
for B,C in combinations(nodes_list,2):
    keyBC = (B,C) if B<C else (C,B)
    timesBC = und.get(keyBC, [])
    if not timesBC:
        continue
    common = neighbors.get(B,set()) & neighbors.get(C,set())
    if not common:
        continue
    for A in common:
        if A==B or A==C:
            continue
        keyAB = (A,B) if A<B else (B,A)
        keyAC = (A,C) if A<C else (C,A)
        timesAB = und.get(keyAB, [])
        timesAC = und.get(keyAC, [])
        if not timesAB or not timesAC:
            continue
        # nested loops but acceptable
        for t1 in timesAB:
            for t2 in timesAC:
                if t1 < t2 and start <= t2 <= end:
                    # find BC time >= t2 and <= t2+800
                    for t3 in timesBC:
                        if t3 >= t2 and t3 <= t2 + 800:
                            results.append((A,B,C,t1,t2,t3))
                            break

print('step_04: found', len(results), 'candidates')
# print unique (B,C) pairs that had candidates and examples
pairs = set()
examples = []
for r in results:
    A,B,C,t1,t2,t3 = r
    pairs.add((B,C))
    if len(examples) < 10:
        examples.append(r)

print('pairs with closure:', len(pairs))
for ex in examples:
    print(ex)

